        return 'unknown-id'
      },
      parentId: 'parent-1',
    })
    expect(result).toEqual([])
  })

  it('should return empty array for empty description', () => {
    const result = traverseDescription({
      info: { title: 'Openapi Document', version: '1.0.0', description: '' },
      generateId: (props) => {
